package com.fullstack.exp232.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.Date; import java.util.UUID;
@Service public class JwtService {private final SecretKey key=Keys.hmacShaKeyFor("FullStackII-Exp232-JWT-Secret-Key-2026-LongEnough".getBytes(StandardCharsets.UTF_8)); public String access(String u){return make(u,"access",600000);} public String refresh(String u){return make(u,"refresh",86400000);} private String make(String u,String type,long ttl){return Jwts.builder().id(UUID.randomUUID().toString()).subject(u).claim("type",type).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+ttl)).signWith(key).compact();} public String username(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload().getSubject();}}
